import { createServer } from 'node:http';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname, extname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const root = dirname(fileURLToPath(import.meta.url));
const publicDir = join(root, 'public');
const dataFile = join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
const mimeTypes = {
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.svg': 'image/svg+xml',
};

await mkdir(dirname(dataFile), { recursive: true });
let books;
try {
  books = JSON.parse(await readFile(dataFile, 'utf8'));
  if (!Array.isArray(books)) throw new Error('Books file must contain an array');
} catch (error) {
  if (error.code !== 'ENOENT') throw error;
  books = [];
  await writeFile(dataFile, '[]\n', 'utf8');
}

let saveQueue = Promise.resolve();
function persistBooks() {
  const snapshot = JSON.stringify(books, null, 2) + '\n';
  saveQueue = saveQueue.catch(() => {}).then(async () => {
    const temporaryFile = `${dataFile}.tmp`;
    await writeFile(temporaryFile, snapshot, 'utf8');
    await rename(temporaryFile, dataFile);
  });
  return saveQueue;
}

function sendJson(response, status, payload) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  response.end(JSON.stringify(payload));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 1_000_000) throw Object.assign(new Error('Request body is too large'), { status: 413 });
  }
  try {
    return JSON.parse(body || '{}');
  } catch {
    throw Object.assign(new Error('Request body must be valid JSON'), { status: 400 });
  }
}

async function serveStatic(response, path) {
  const filename = path === '/' || /^\/book\/[\w-]+\/?$/.test(path) ? 'index.html' : path.slice(1);
  if (!['index.html', 'app.js', 'styles.css'].includes(filename)) {
    response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    response.end('Not found');
    return;
  }
  try {
    const content = await readFile(join(publicDir, filename));
    response.writeHead(200, {
      'Content-Type': filename === 'index.html' ? 'text/html; charset=utf-8' : mimeTypes[extname(filename)],
      'Cache-Control': 'no-cache',
    });
    response.end(content);
  } catch {
    response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    response.end('Not found');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  const path = url.pathname;

  if (path === '/api/books' && request.method === 'GET') {
    sendJson(response, 200, books);
    return;
  }

  if (path === '/api/books' && request.method === 'POST') {
    try {
      const body = await readJson(request);
      const title = typeof body.title === 'string' ? body.title.trim() : '';
      const author = typeof body.author === 'string' ? body.author.trim() : '';
      const notes = typeof body.notes === 'string' ? body.notes.trim() : '';
      if (!title || !author) {
        sendJson(response, 400, { error: 'Add a title and author to save this book.' });
        return;
      }
      const book = {
        id: randomUUID(),
        title,
        author,
        notes,
        status: 'reading',
        createdAt: new Date().toISOString(),
        finishedAt: null,
      };
      books.unshift(book);
      await persistBooks();
      sendJson(response, 201, book);
    } catch (error) {
      sendJson(response, error.status || 500, { error: error.status ? error.message : 'Could not save the book.' });
    }
    return;
  }

  const bookMatch = path.match(/^\/api\/books\/([\w-]+)$/);
  if (bookMatch && request.method === 'GET') {
    const book = books.find((item) => item.id === bookMatch[1]);
    sendJson(response, book ? 200 : 404, book || { error: 'Book not found.' });
    return;
  }
  if (bookMatch && request.method === 'PATCH') {
    const book = books.find((item) => item.id === bookMatch[1]);
    if (!book) {
      sendJson(response, 404, { error: 'Book not found.' });
      return;
    }
    try {
      const body = await readJson(request);
      if (body.status !== 'finished') {
        sendJson(response, 400, { error: 'The only supported update is marking a book finished.' });
        return;
      }
      book.status = 'finished';
      book.finishedAt = book.finishedAt || new Date().toISOString();
      await persistBooks();
      sendJson(response, 200, book);
    } catch (error) {
      sendJson(response, error.status || 500, { error: error.status ? error.message : 'Could not update the book.' });
    }
    return;
  }

  if (request.method === 'GET') {
    await serveStatic(response, path);
    return;
  }
  sendJson(response, 405, { error: 'Method not allowed.' });
});

server.listen(port, '0.0.0.0', () => {
  console.log(`Reading list is ready at http://localhost:${port}`);
});
const app = document.querySelector('#app');
const dialog = document.querySelector('#add-dialog');
const form = document.querySelector('#add-form');
const toast = document.querySelector('#toast');
const formError = document.querySelector('#form-error');
let books = [];
let activeView = 'reading';
let toastTimer;

const bookIcon = `<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 5.5c3.1-1 5.8-.3 8 1.7v12c-2.2-2-4.9-2.7-8-1.7v-12Z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M19 5.5c-3.1-1-5.8-.3-8 1.7v12c2.2-2 4.9-2.7 8-1.7v-12Z" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M13 7.2v12" stroke="currentColor" stroke-width="1.4"/></svg>`;
const checkIcon = `<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m5 10.2 3.1 3.1L15.4 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>`;

function escapeHtml(value = '') {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function formatDate(value, options = { month: 'short', day: 'numeric', year: 'numeric' }) {
  if (!value) return '';
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat(undefined, options).format(date);
}

function notify(message) {
  toast.textContent = message;
  toast.classList.add('visible');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toast.classList.remove('visible'), 2600);
}

function openAddDialog() {
  formError.textContent = '';
  form.reset();
  dialog.showModal();
  requestAnimationFrame(() => document.querySelector('#book-title').focus());
}

async function request(url, options) {
  const response = await fetch(url, options);
  const result = await response.json();
  if (!response.ok) throw new Error(result.error || 'Something went wrong.');
  return result;
}

function renderList() {
  const reading = books.filter((book) => book.status === 'reading');
  const finished = books.filter((book) => book.status === 'finished')
    .sort((a, b) => new Date(b.finishedAt || 0) - new Date(a.finishedAt || 0));
  const visibleBooks = activeView === 'reading' ? reading : finished;
  const listContent = visibleBooks.length
    ? `<ul class="book-list">${visibleBooks.map((book) => {
      const date = activeView === 'reading' ? book.createdAt : book.finishedAt;
      const dateLabel = activeView === 'reading' ? 'Added' : 'Finished';
      return `<li class="book-item">
        <a class="book-link" href="/book/${encodeURIComponent(book.id)}">
          <span class="book-spine">${bookIcon}</span>
          <span class="book-text">
            <span class="book-title">${escapeHtml(book.title)}</span>
            <span class="book-author">${escapeHtml(book.author)}</span>
          </span>
          <span class="book-meta">${date ? `${dateLabel} ${escapeHtml(formatDate(date, { month: 'short', day: 'numeric' }))}` : ''}</span>
        </a>
        ${activeView === 'reading'
          ? `<button class="finish-button" type="button" data-finish="${escapeHtml(book.id)}">Mark finished</button>`
          : `<span class="finished-mark">${checkIcon}<span>Finished</span></span>`}
      </li>`;
    }).join('')}</ul>`
    : `<div class="empty-state">
        <span class="empty-illustration">${bookIcon}</span>
        <h2>${activeView === 'reading' ? 'Your next chapter starts here.' : 'Your finished shelf is waiting.'}</h2>
        <p>${activeView === 'reading' ? 'Add a book you’re reading and keep your thoughts close.' : 'Books you finish will find a home here.'}</p>
        ${activeView === 'reading' ? '<button class="button button-primary" type="button" data-add><span class="plus">+</span> Add your first book</button>' : ''}
      </div>`;

  app.innerHTML = `<section class="library">
    <div class="hero">
      <div>
        <p class="eyebrow">YOUR PERSONAL LIBRARY</p>
        <h1>A little record<br />of your reading.</h1>
        <p class="hero-copy">Keep the books you’re in the middle of, and the ones that stayed with you.</p>
      </div>
      <button class="button button-primary button-add" type="button" data-add><span class="plus">+</span> Add a book</button>
    </div>
    <section class="library-card" aria-label="Your books">
      <div class="tabs" role="tablist" aria-label="Book status">
        <button class="tab" role="tab" id="tab-reading" aria-selected="${activeView === 'reading'}" aria-controls="book-panel" data-view="reading">Reading <span class="count">${reading.length}</span></button>
        <button class="tab" role="tab" id="tab-finished" aria-selected="${activeView === 'finished'}" aria-controls="book-panel" data-view="finished">Finished <span class="count">${finished.length}</span></button>
      </div>
      <div id="book-panel" role="tabpanel" aria-labelledby="tab-${activeView}">${listContent}</div>
    </section>
  </section>`;

  app.querySelectorAll('[data-add]').forEach((button) => button.addEventListener('click', openAddDialog));
  app.querySelectorAll('[data-view]').forEach((button) => button.addEventListener('click', () => {
    activeView = button.dataset.view;
    renderList();
  }));
  app.querySelectorAll('[data-finish]').forEach((button) => button.addEventListener('click', () => finishBook(button.dataset.finish, button)));
}

function renderNotFound() {
  app.innerHTML = `<section class="not-found"><p class="eyebrow">NOT ON THIS SHELF</p><h1>We couldn’t find that book.</h1><p>It may have been removed, or the link might be incomplete.</p><a class="button button-primary" href="/">Back to your reading list</a></section>`;
}

async function renderBook(id) {
  try {
    const book = await request(`/api/books/${encodeURIComponent(id)}`);
    const finished = book.status === 'finished';
    app.innerHTML = `<section class="detail-page">
      <a class="back-link" href="/"><span aria-hidden="true">←</span> Your reading list</a>
      <article class="detail-card">
        <header class="detail-top">
          <p class="eyebrow">A BOOK IN YOUR LIBRARY</p>
          <div class="detail-book-heading">
            <span class="detail-spine">${bookIcon}</span>
            <div><h1 class="detail-title">${escapeHtml(book.title)}</h1><p class="detail-author">by ${escapeHtml(book.author)}</p></div>
          </div>
        </header>
        <div class="detail-body">
          <div class="detail-meta-row">
            <span class="status-pill ${finished ? 'finished' : ''}"><span class="status-dot"></span>${finished ? 'FINISHED' : 'CURRENTLY READING'}</span>
            <span class="added-date">${finished && book.finishedAt ? `Finished ${escapeHtml(formatDate(book.finishedAt))}` : `Added ${escapeHtml(formatDate(book.createdAt))}`}</span>
          </div>
          <h2 class="notes-heading">MY NOTES</h2>
          <div class="notes-content ${book.notes ? '' : 'notes-empty'}">${book.notes ? escapeHtml(book.notes) : 'No notes yet.'}</div>
          <div class="detail-actions">
            ${finished ? '' : `<button class="button button-primary" type="button" data-finish="${escapeHtml(book.id)}">${checkIcon} Mark as finished</button>`}
            <button class="button button-quiet" type="button" data-share><span class="share-symbol" aria-hidden="true">↗</span> Copy link</button>
          </div>
        </div>
      </article>
    </section>`;
    const finishButton = app.querySelector('[data-finish]');
    if (finishButton) finishButton.addEventListener('click', () => finishBook(book.id, finishButton, true));
    app.querySelector('[data-share]').addEventListener('click', copyBookLink);
  } catch {
    renderNotFound();
  }
}

async function finishBook(id, button, onDetail = false) {
  button.disabled = true;
  try {
    const updated = await request(`/api/books/${encodeURIComponent(id)}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status: 'finished' }),
    });
    books = books.map((book) => book.id === id ? updated : book);
    if (onDetail) {
      renderBook(id);
      notify('Marked as finished.');
    } else {
      renderList();
      notify('Moved to your finished shelf.');
    }
  } catch (error) {
    button.disabled = false;
    notify(error.message);
  }
}

async function copyBookLink() {
  try {
    await navigator.clipboard.writeText(window.location.href);
    notify('Book link copied.');
  } catch {
    const temporary = document.createElement('textarea');
    temporary.value = window.location.href;
    temporary.setAttribute('readonly', '');
    temporary.style.position = 'fixed';
    temporary.style.opacity = '0';
    document.body.append(temporary);
    temporary.select();
    const copied = document.execCommand('copy');
    temporary.remove();
    notify(copied ? 'Book link copied.' : 'Copy this page’s address to share the book.');
  }
}

form.addEventListener('submit', async (event) => {
  event.preventDefault();
  formError.textContent = '';
  const submitButton = document.querySelector('#save-book');
  submitButton.disabled = true;
  submitButton.textContent = 'Saving…';
  const formData = new FormData(form);
  try {
    const book = await request('/api/books', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: formData.get('title'),
        author: formData.get('author'),
        notes: formData.get('notes'),
      }),
    });
    books.unshift(book);
    activeView = 'reading';
    dialog.close();
    renderList();
    notify('Added to your reading list.');
  } catch (error) {
    formError.textContent = error.message;
  } finally {
    submitButton.disabled = false;
    submitButton.textContent = 'Add to reading';
  }
});

document.querySelectorAll('[data-close-dialog]').forEach((button) => button.addEventListener('click', () => dialog.close()));
dialog.addEventListener('click', (event) => {
  if (event.target === dialog) dialog.close();
});

async function start() {
  try {
    books = await request('/api/books');
    const match = window.location.pathname.match(/^\/book\/([\w-]+)\/?$/);
    if (match) await renderBook(match[1]);
    else renderList();
  } catch {
    app.innerHTML = `<section class="not-found"><p class="eyebrow">A SMALL PAUSE</p><h1>Your shelf didn’t open.</h1><p>Refresh the page to try again.</p></section>`;
  }
}

start();
